const journalKey='wildride-practice-v1',validStates=['new','learning','practiced'],byId=new Map(SKILLS.map(s=>[s.id,s]));
let journal={},storageAvailable=true,selectedLevel='all',currentSkill=null;
let accountMode='checking',accountRevision=0,accountMember=null;
let activeTopic='balance';
const syncBanner=document.createElement('div');syncBanner.className='account-sync';syncBanner.textContent='正在確認會員與練習紀錄…';document.querySelector('.skill-dashboard').prepend(syncBanner);
function syncMessage(message,error=false){syncBanner.replaceChildren();const span=document.createElement('span');span.textContent=message;const link=document.createElement('a');link.href='member.html';link.textContent=accountMember?'會員中心 →':'登入／註冊 →';syncBanner.append(span,link);syncBanner.classList.toggle('error',error)}
function sanitizeJournal(input){const clean={};if(!input||typeof input!=='object')return clean;SKILLS.forEach(s=>{const v=input[s.id];if(v&&validStates.includes(v.status))clean[s.id]={status:v.status,notes:typeof v.notes==='string'?v.notes.slice(0,1200):'',updatedAt:typeof v.updatedAt==='string'?v.updatedAt:''}});return clean}
try{journal=sanitizeJournal(JSON.parse(localStorage.getItem(journalKey)||'{}'))}catch{storageAvailable=false;document.getElementById('storage-note').textContent='此瀏覽器無法讀取本機紀錄。你仍可瀏覽及暫存本次進度，離開前請下載紀錄。'}
const statusOf=id=>journal[id]?.status||'new',statusLabel={new:'○ 尚未開始',learning:'◐ 正在學習',practiced:'● 已練習（自記）'},colors={L1:'#285e43',L2:'#af572d',L3:'#343c39',SP:'#73763f'};
function recommended(){return SKILLS.filter(s=>statusOf(s.id)!=='practiced'&&s.requires.every(id=>statusOf(id)==='practiced'))}
async function persist(){if(accountMode==='checking'||accountMode==='error')throw Error('會員紀錄尚未載入，請重新整理或先下載筆記備份。');if(accountMode==='member'){try{const result=await WildRideMember.request('progress',{journal,revision:accountRevision});accountRevision=result.revision;syncMessage(accountMember.name+'｜會員紀錄已儲存');return true}catch(e){syncMessage(e.message,true);if(e.status===401||e.status===403)accountMode='error';throw e}}try{localStorage.setItem(journalKey,JSON.stringify(journal));storageAvailable=true;return true}catch{storageAvailable=false;document.getElementById('storage-note').textContent='本機儲存不可用，這次紀錄只保留在目前頁面。離開前請下載紀錄。';return false}}
function button(label,handler){const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',handler);return b}
const filterHost=document.getElementById('level-filters');[['all','全部'],...SKILL_LEVELS.map(l=>[l.id,l.id==='SP'?'獨立專項':l.id])].forEach(([id,label])=>{const b=button(label,()=>{selectedLevel=id;filterHost.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x.dataset.level===id));renderMap()});if(id==='SP'){b.prepend(specialtyIcon('sp'))}if(id.startsWith('L')){const img=document.createElement('img');img.src='assets/levels/'+id.toLowerCase()+'.svg';img.alt='';b.prepend(img)}b.dataset.level=id;b.setAttribute('aria-pressed',id==='all');filterHost.append(b)});
function updateDashboard(){renderTopics();const n=SKILLS.filter(s=>statusOf(s.id)==='practiced').length;document.getElementById('practiced-count').textContent=n;document.getElementById('overall-progress').value=n;document.getElementById('overall-progress').max=SKILLS.length;document.getElementById('learning-count').textContent=SKILLS.filter(s=>statusOf(s.id)==='learning').length+' 項正在學習';const host=document.getElementById('next-step');host.replaceChildren();const p=document.createElement('p');p.textContent='根據自記進度，建議下一步：';host.append(p);const next=recommended().slice(0,3);if(next.length)next.forEach(s=>host.append(button(s.name+' ↗',()=>showSkill(s.id))));else{const span=document.createElement('span');span.textContent='所有技能皆已自記練習，可與教練討論複訓與實作評量。';host.append(span)}}
function levelEmblem(level){if(['L1','L2','L3'].includes(level)){const img=document.createElement('img');img.src='assets/levels/'+level.toLowerCase()+'.svg';img.alt='';img.className='level-emblem';return img}const svg=specialtyIcon('sp');svg.classList.add('sp-emblem');return svg}
function renderTopics(){renderLearningTree()}
function selectTopic(id){activeTopic=id;selectedLevel='all';document.getElementById('skill-search').value='';filterHost.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.level==='all'));renderTopics();renderMap();document.getElementById('map').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
document.getElementById('view-all-skills').addEventListener('click',()=>selectTopic('all'));
function renderMap(){filterHost.querySelectorAll('button img').forEach(img=>{const b=img.parentElement;img.src='assets/levels/'+b.dataset.level.toLowerCase()+(b.getAttribute('aria-pressed')==='true'?'-inverse':'')+'.svg'});const query=document.getElementById('skill-search').value.trim().toLowerCase();const topic=SKILL_TOPICS.find(t=>t.id===activeTopic);document.getElementById('selected-topic-title').textContent=topic?topic.name:'全部技能';const host=document.getElementById('skill-groups');host.replaceChildren();let count=0;const next=new Set(recommended().map(s=>s.id));SKILL_LEVELS.filter(l=>selectedLevel==='all'||l.id===selectedLevel).forEach(level=>{const visible=SKILLS.filter(s=>s.level===level.id&&(!topic||topic.skills.includes(s.id))&&[s.name,s.description,SKILL_BRANCHES[s.branch],s.level].join(' ').toLowerCase().includes(query));if(!visible.length)return;count+=visible.length;const group=document.createElement('section');group.className='skill-group';const top=document.createElement('div');top.className='skill-group-title';const h=document.createElement('h3');h.textContent=level.id+' / '+level.title;top.append(levelEmblem(level.id),h);group.append(top);const cards=document.createElement('div');cards.className='skill-lanes';visible.forEach(s=>{const b=document.createElement('button');b.type='button';b.className='skill-node'+(next.has(s.id)?' recommended':'');b.id='node-'+s.id;b.dataset.skill=s.id;b.dataset.status=statusOf(s.id);b.style.setProperty('--level-color',colors[s.level]);const meta=document.createElement('span');meta.className='node-meta';meta.textContent=s.level+' / '+topicForSkill(s.id).en;const title=document.createElement('h4');title.textContent=s.name;const status=document.createElement('span');status.className='node-status';status.textContent=statusLabel[statusOf(s.id)];const req=document.createElement('span');req.className='node-prereq';req.textContent=s.requires.length?'先修 '+s.requires.length+' 項 · 查看學習路線 ↗':'起點技能 · 從這裡開始 ↗';b.append(skillIdentityIcon(s.id),meta,title,status,req);b.addEventListener('click',()=>showSkill(s.id));cards.append(b)});group.append(cards);host.append(group)});document.getElementById('current-topic-count').textContent=count+' 項技能';document.getElementById('no-skills').hidden=count!==0}
function drawConnections(){} // Prerequisites are opened from each skill, keeping the overview concise.
const dialog=document.getElementById('skill-dialog');function showSkill(id){const s=byId.get(id);if(!s)return;currentSkill=s;document.getElementById('dialog-emblem').replaceChildren(RIDER_SKILL_MARKS[s.id]?riderSkillIcon(s.id):(SPECIALTY_MARKS[s.id]?specialtyIcon(s.id):levelEmblem(s.level)));document.getElementById('skill-meta').textContent=s.level+' / '+SKILL_BRANCHES[s.branch];document.getElementById('skill-title').textContent=s.name;document.getElementById('skill-description').textContent=s.description;const req=document.getElementById('skill-prerequisites');req.replaceChildren();if(s.requires.length)s.requires.forEach(id=>{const p=byId.get(id);req.append(button(p.name+' · '+statusLabel[statusOf(id)],()=>showSkill(id)))});else req.textContent='這是學習起點，先和教練確認車況、護具與個人條件。';const checks=document.getElementById('skill-checks');checks.replaceChildren(...s.checks.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));document.getElementById('skill-status').value=statusOf(id);document.getElementById('skill-notes').value=journal[id]?.notes||'';document.getElementById('save-feedback').textContent='';if(!dialog.open)dialog.showModal()}
document.getElementById('save-skill').addEventListener('click',async e=>{if(!currentSkill)return;e.target.disabled=true;const status=document.getElementById('skill-status').value;const notes=document.getElementById('skill-notes').value.slice(0,1200);journal[currentSkill.id]={status:validStates.includes(status)?status:'new',notes,updatedAt:new Date().toISOString()};try{const saved=await persist();updateDashboard();renderMap();const incomplete=currentSkill.requires.filter(id=>statusOf(id)!=='practiced');document.getElementById('save-feedback').textContent=(accountMode==='member'?'已儲存至目前會員帳號。':saved?'已儲存至訪客本機紀錄。':'已暫存本次頁面，請下載紀錄。')+(status==='practiced'&&incomplete.length?'部分建議先修尚無練習紀錄，可與教練確認學習順序。':'')}catch(err){document.getElementById('save-feedback').textContent='尚未儲存：'+err.message+' 請先下載目前筆記備份。';updateDashboard();renderMap()}finally{e.target.disabled=false}});document.querySelector('.skill-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.getElementById('export-progress').addEventListener('click',()=>{const data={academy:'WildRide Academy',type:'self-reported-practice-journal',version:1,exportedAt:new Date().toISOString(),notice:'個人自記練習紀錄；不代表教練認證、級別通過或證書。',skills:SKILLS.map(s=>({id:s.id,level:s.level,name:s.name,status:statusOf(s.id),notes:journal[s.id]?.notes||'',updatedAt:journal[s.id]?.updatedAt||null}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='馭野_個人練習紀錄_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
document.getElementById('reset-progress').addEventListener('click',async e=>{if(!confirm(accountMode==='member'?'清除目前會員帳號的全部自記練習紀錄？請先下載備份。':'清除此瀏覽器的訪客練習紀錄？請先下載備份。'))return;e.target.disabled=true;const previous=journal;journal={};try{await persist();updateDashboard();renderMap()}catch(err){journal=previous;syncMessage(err.message,true)}finally{e.target.disabled=false}});document.getElementById('skill-search').addEventListener('input',renderMap);window.addEventListener('resize',()=>requestAnimationFrame(drawConnections));
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='選單 ＋'}menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.textContent=open?'關閉 ×':'選單 ＋'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});updateDashboard();renderMap();

async function loadAccountJournal(){const save=document.getElementById('save-skill');save.disabled=true;document.getElementById('reset-progress').disabled=true;try{const session=await WildRideMember.session();if(session.member){accountMember=session.member;const data=await WildRideMember.request('progress');journal=sanitizeJournal(data.journal);accountRevision=data.revision;accountMode='member';document.querySelector('.local-note').textContent='你正在使用會員帳號記錄練習。進度與筆記保存於會員服務，自記已練習不等同教練認證。';document.getElementById('reset-progress').textContent='清除會員自記紀錄';syncMessage(accountMember.name+'｜已載入你的會員技能樹')}else{accountMode='guest';syncMessage('訪客模式｜紀錄只存於此瀏覽器，可登入後由會員中心確認合併。')}}catch(err){if(accountMember){accountMode='error';journal={};syncMessage('會員紀錄載入失敗，暫停儲存。請重新登入或重新整理。',true)}else{accountMode='guest';syncMessage('會員服務未連線，目前為訪客本機紀錄。',true)}}finally{save.disabled=accountMode==='error';document.getElementById('reset-progress').disabled=accountMode==='error';updateDashboard();renderMap()}}loadAccountJournal().then(()=>{const query=new URLSearchParams(location.search),requested=query.get('skill'),topic=query.get('topic');if(requested&&byId.has(requested)){treeSelected=requested;treeTopic=topicForSkill(requested).id;renderTopics();showSkill(requested)}else if(topic&&SKILL_TOPICS.some(t=>t.id===topic)){treeTopic=topic;renderTopics()}});
